Legacy refactor, characterization-first. Save the following as /workspace/sales_report.py exactly as given, then lock in its behavior with tests BEFORE changing a single line:

import sys

REGIONS = {}
GRAND_TOTAL = 0
LINES = 0

def process(path):
    global GRAND_TOTAL, LINES
    f = open(path)
    for line in f:
        line = line.strip()
        if line == "":
            continue
        if line.startswith("#"):
            continue
        parts = line.split(",")
        if len(parts) == 4:
            region = parts[0].strip()
            rep = parts[1].strip()
            units = parts[2].strip()
            price = parts[3].strip()
            if region != "":
                if units.isdigit():
                    try:
                        p = float(price)
                    except ValueError:
                        p = 0.0
                    amount = int(units) * p
                    GRAND_TOTAL = GRAND_TOTAL + amount
                    LINES = LINES + 1
                    if region in REGIONS:
                        if rep in REGIONS[region]:
                            REGIONS[region][rep] = REGIONS[region][rep] + amount
                        else:
                            REGIONS[region][rep] = amount
                    else:
                        REGIONS[region] = {}
                        REGIONS[region][rep] = amount
    f.close()

def report():
    out = ""
    out = out + "SALES REPORT\n"
    out = out + "============\n"
    for region in sorted(REGIONS.keys()):
        out = out + region + "\n"
        best = None
        best_amt = -1
        total = 0
        for rep in sorted(REGIONS[region].keys()):
            amt = REGIONS[region][rep]
            total = total + amt
            out = out + "  " + rep + ": " + ("%.2f" % amt) + "\n"
            if amt > best_amt:
                best_amt = amt
                best = rep
        out = out + "  region total: " + ("%.2f" % total) + "\n"
        out = out + "  top rep: " + best + "\n"
    out = out + "grand total: " + ("%.2f" % GRAND_TOTAL) + "\n"
    out = out + "lines: " + str(LINES) + "\n"
    return out

if __name__ == "__main__":
    process(sys.argv[1])
    print(report(), end="")

